ontent_1975 = f.read()\nwith open('/app/resources/treasury_bulletin_1976_03_page_38.txt', 'r') as f:\n    content_1976 = f.read()\n\n# Try to extract totals - looking at each page's structure\nprint(\"Checking content structure for 1972:\")\n# Find the rows that contain year totals\nlines = content_1972.split('\\n')\nfor i, line in enumerate(lines):\n    if 'Total</td>' in line and i > 0:\n        prev_line = lines[i-1]\n        if '197' in prev_line:\n            print(f\"Found: Year from {prev_line[:100]}... Total line: {line[:150]}\")\n\nprint(\"\\n1972 full totals extraction:\")\ntotals_1972 = extract_totals(content_1972, [1972, 1973, 1974, 1975, 1976])\nprint(totals_1972)\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
